package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.config.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.content.*;
import com.lianxibu.site.service.content.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

/** Formal cold provider registry with native full reference validity and current content state. Transports remain fictional. */
class CatalogDayReportProofNativeTest {
    boolean mysql(){return false;}
    CatalogAnalysisReportCandidateTest helper(){return new CatalogAnalysisReportCandidateTest(){@Override boolean mysql(){return CatalogDayReportProofNativeTest.this.mysql();}};}
    CatalogDayReportProofConfiguration.Components registry(CatalogAnalysisReportCandidateTest.Native f){var original=f.fixture().built().data().data().data().data();var nativeFixture=original.f();var map=new LinkedHashMap<String,CatalogDayAnalysisProofGraph>();for(String category:CatalogSourceProofConfiguration.CATEGORIES){var source=category.equals(f.completed().reservation().category())?nativeFixture.graph:new CatalogSourceProofGraph(f.fixture().f().source,f.fixture().f().tx,f.fixture().clock(),()->new FrozenGenerationSettings(7,List.of("fictional"),List.of()),()->true,category);map.put(category,new CatalogDayAnalysisProofGraph(f.fixture().f().source,f.fixture().f().tx,f.fixture().clock(),nativeFixture.cohorts,nativeFixture.runs,source,()->new FrozenGenerationSettings(7,List.of("fictional"),List.of()),()->true,category));}return CatalogDayReportProofConfiguration.assemble(f.fixture().f().source,f.fixture().f().tx,f.fixture().clock(),new CatalogDayAnalysisProofConfiguration.Graphs(map));}
    @Test void FourActualCategoriesRouteOriginalWholeCandidatesThroughNativeReferenceClosureValidity(){for(String category:CatalogSourceProofConfiguration.CATEGORIES){var f=helper().nativeCompletion(category,false);var service=registry(f).component(category);var component=service.capture(f.fixture().day(),f.cutoff());assertEquals(1,component.candidates().size());assertTrue(component.candidates().getFirst().evidence().effectiveValid());assertFalse(component.candidates().getFirst().evidence().blocked());assertEquals(f.completed().bodyJson(),component.candidates().getFirst().evidence().bodyJson());assertTrue(component.missing().isEmpty());assertEquals(2,f.fixture().f().sends);}}
    @Test void NativeLeafInvalidationExcludesBodyAndInvalidatesPreviouslyCapturedEligibility(){var f=helper().nativeCompletion("agent",false);var service=registry(f).component("agent");var original=service.capture(f.fixture().day(),f.cutoff());var context=FrozenApplicationContext.fromJson(CanonicalJson.parse(f.completed().snapshotJson()).get(FrozenApplicationContext.FIELD));var leaf=context.referenceTargets().getFirst();var clock=f.fixture().clock();var source=f.fixture().f().source;var versions=new FrozenContentVersionService(new JdbcFrozenContentVersions(source));var contents=new ContentReadService(new JdbcContentReads(source),f.fixture().f().tx,ContentReadService.denyUnverifiedReferences());var writer=new ContentReviewWriteService(new JdbcReviewPublication(source),new GeneratedContentService(new JdbcGeneratedContents(source),clock),clock);var validity=new VersionValidityService(f.fixture().f().writes,new VersionValidityJdbcStore(f.fixture().built().data().validity(),new JdbcValidityPropagation(source),versions,contents,writer,clock,"fictional-owner",null));var command=new VersionValidityService.Command(leaf,0,VersionValidityService.Action.INVALIDATE,"Fictional invalid original evidence",null);var result=validity.change(command,new SharedWriteExecutor.ActionContext("fictional-report-leaf-invalidation",f.completed().version().inputJobId(),f.completed().inputHash()));assertFalse(result.effectiveValid());var reads=new TransactionTemplate(f.fixture().f().tx);reads.setReadOnly(true);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);reads.execute(s->{assertThrows(RuntimeException.class,()->service.verifyObserved(original));return null;});var fresh=service.capture(f.fixture().day(),f.cutoff());assertFalse(fresh.candidates().getFirst().evidence().effectiveValid());assertEquals(2,f.fixture().f().sends);}
    @Test void BlockedCurrentContentIsExcludedWithoutChangingOriginalBodyOrVersion(){var f=helper().nativeCompletion("model",false);var service=registry(f).component("model");f.fixture().f().jdbc.update("UPDATE contents SET state='blocked' WHERE id=?",f.completed().version().contentId());var component=service.capture(f.fixture().day(),f.cutoff());assertTrue(component.candidates().getFirst().evidence().blocked());assertEquals(f.completed().bodyJson(),component.candidates().getFirst().evidence().bodyJson());assertEquals(f.completed().version(),ContentVersionKey.fromJson(CanonicalJson.parse(component.referenceJson().getFirst())));assertEquals(2,f.fixture().f().sends);}
}
